import { useState } from 'react';

function ClientSideButton({ userId }) {
  const [liked, setLiked] = useState(false);
  return (
    <button onClick={() => setLiked(!liked)}>
      {liked ? 'Liked' : 'Like'}
    </button>
  );
}

import { useId, useTransition, useDeferredValue } from 'react';

function Form() {
  const id = useId();
  return (
    <div>
      <label htmlFor={`${id}-name`}>Name</label>
      <input id={`${id}-name`} />
    </div>
  );
}

function SearchableList({ items }) {
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);

  // deferredQuery会在输入稳定后才更新
  const filtered = items.filter(item =>
    item.name.includes(deferredQuery)
  );

  return (
    <div>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      <List items={filtered} />
    </div>
  );
}

type IsString<T> = T extends string ? true : false;
type A = IsString<string>;  // true
type B = IsString<number>;  // false

// infer提取类型
type UnpackPromise<T> = T extends Promise<infer U> ? U : T;
type C = UnpackPromise<Promise<string>>;  // string
type D = UnpackPromise<number>;  // number

// 分布式条件类型
type ToArray<T> = T extends any ? T[] : never;
type E = ToArray<string | number>;  // string[] | number[]

// 实用：获取函数参数类型
type MyParameters<T> = T extends (...args: infer P) => any ? P : never;
function greet(name: string, age: number) {}
type GreetParams = MyParameters<typeof greet>;  // [string, number]

type MyReadonly<T> = {
  readonly [P in keyof T]: T[P];
};

type MyPartial<T> = {
  [P in keyof T]?: T[P];
};

interface User {
  name: string;
  age: number;
  email: string;
}

type ReadonlyUser = MyReadonly<User>;
type PartialUser = MyPartial<User>;

// Pick：选取部分属性
type UserBasic = Pick<User, 'name' | 'age'>;

// Omit：排除部分属性
type UserWithoutEmail = Omit<User, 'email'>;

// Record：创建类型对象
type UserRoles = Record<string, string[]>;
const roles: UserRoles = {
  admin: ['read', 'write', 'delete'],
  user: ['read']
};

type EventName = `on${Capitalize<'click' | 'focus' | 'blur'>}`;
// 'onClick' | 'onFocus' | 'onBlur'

type CSSProperty = `${'margin' | 'padding'}-${'top' | 'right' | 'bottom' | 'left'}`;
// 'margin-top' | 'margin-right' | ... | 'padding-left'

// 实际应用：类型安全的事件绑定
type EventHandler<T extends string> = `on${Capitalize<T>}`;

type DOMEvents = 'click' | 'focus' | 'blur' | 'change';
type DOMEventHandlers = EventHandler<DOMEvents>;
// 'onClick' | 'onFocus' | 'onBlur' | 'onChange'

// 路由参数提取
type ExtractParams<T extends string> =
  T extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : T extends `${string}:${infer Param}`
    ? Param
    : never;

type Params = ExtractParams<'/users/:userId/posts/:postId'>;
// 'userId' | 'postId'

type DeepReadonly<T> = {
  readonly [P in keyof T]: T[P] extends object
    ? DeepReadonly<T[P]>
    : T[P];
};

type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object
    ? DeepPartial<T[P]>
    : T[P];
};

interface Config {
